local MournPlotDialog = Class("MournPlotDialog")
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')
local BattleType = {
	Chapter = 1,
	Battle = 2,
}
--region lifecycle
function MournPlotDialog:__init()
	self._coWarmUp = nil
	self._coFillSelf = nil
	self._hasBeenWarmUp = nil
end

function MournPlotDialog:__delete()
	self._coWarmUp = nil
	self._coFillSelf = nil
	self._hasBeenWarmUp = nil
end

function MournPlotDialog:Awake()
	--self:WarmUp()
	self:AddUIClick()
end


function MournPlotDialog:AddUIClick()
	SetButtonAction(self.BtnClose,Bind(self,self.OnBtnCloseClick))
	SetButtonAction(self.BtnGo,Bind(self,self.OnBtnGoClick))
end

function MournPlotDialog:OnBtnCloseClick()
	UIModule.BackDialog()
end

function MournPlotDialog:OnBtnGoClick()
	local vo = self._data[self.curIndex]
	if isNotNull(vo) then
		local isFinish = ActivityMournUtils.IsUnLockPlot(vo.id)
		if isFinish then
			self:GoToFight(vo)
		else
			local isUnLock = ActivityMournUtils.IsUnLockPlot(vo.unlockPlot)
			if isUnLock  then
				local isUse = ActivityMournUtils.IsUseItem(vo)
				if not isUse then
					local isEnough = GoodsUtils.GetThingNo(vo.unlockItem) >= vo.unlockNum
					if not isEnough then
						local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(vo.unlockItem)
						if goodsVo then
							GameUtils.Toast(localize("_name_不足",{_name_ = goodsVo.name}))
						end
						return
					end
					local activityData = ActivityMournUtils:GetActivityData()
					GameUtils.Request(Interfaces.ActivityTowerChangeUnLockPlot,{activityUuid = activityData.id , questId = vo.id},function(request,response)
						if checkNumber(response.errCode) == 0 then
							GoodsUtils.DrawRewards({ { goodsId = vo.unlockItem, num = -vo.unlockNum} })
							ActivityMournUtils.UpdateItemLockPlot(vo.id)
							self:GoToFight(vo)
						end
					end)
				else
					self:GoToFight(vo)
				end
			else
				GameUtils.Toast(localize("请先通关前置关卡"))
			end
		end
	end
end

function MournPlotDialog:GoToFight(data)
	if data.type == BattleType.Chapter then
		self:EnterChapterStory(data)
	elseif data.type == BattleType.Battle then
		self:EnterChapterBattle(data)
	end
end

function MournPlotDialog:EnterChapterStory(data)
	local chapterId = data.plotId
	CfUtils.StartCoroutineWithBlocker(function()
		xTry(function()
			local isFinish = false
			ChapterUtils.ProcessChapter(checkNumber(chapterId), function(go)
				self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
				URPCameraController:SetMainCameraActive(false)
				UINavigationBarRoot.Instance:SetActive(false)
				self._plotGo = go
				isFinish = true
			end, function()
				self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
				URPCameraController:SetMainCameraActive(true)
				UINavigationBarRoot.Instance:SetActive(true)
				self:OnStoryEnd(data)
				CfUtils.SafeDelete(self._plotGo)
			end)
			while not isFinish do
				coroutine.yield()
			end
		end)
	end)
end

function MournPlotDialog:OnStoryEnd(data)
	local isPass = ActivityMournUtils.IsUnLockPlot(data.id)
	if isPass then
		return
	end
	local activityData = ActivityMournUtils:GetActivityData()
	GameUtils.Request(Interfaces.ActivityTowerChangePlot, {activityUuid = activityData.id, questId = data.id }, function(request, response)
		if checkNumber(response.errCode) == 0 then
			local responseData = checkTable(response.data)
			ActivityMournUtils.UpdateChapterInfo(data.id)
			local index = self:GetCurSelectIndex()
			if index > self.curIndex then
				self:SetLockState(index,false)
				self:OnBtnNodeClick(index)
			else
				self:RefreshChapterInfo()
			end
			if #responseData.rewards > 0 then
				GoodsUtils.DrawRewards(responseData.rewards)
				UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
				
				end } })
			end
		end
	end)
end

function MournPlotDialog:RefreshShow()
	local index = self:GetCurSelectIndex()
	self:OnBtnNodeClick(index)
end

function MournPlotDialog:GetCurSelectIndex()
	local index = 1
	for i, v in pairs(self._data) do
		local isUnLock = ActivityMournUtils.IsUnLockPlot(v.unlockPlot)
		if isUnLock then
			index = i
		end
	end
	return index
end

function MournPlotDialog:WarmUp()
	if self._hasBeenWarmUp then return end
	if isNotNull(self._coWarmUp) then return end
	self._coWarmUp = cs_coroutine.start(function()
		for i = 1, 3, 1 do
			self.BtnCheckpointList:ExpandPool()
			cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.02))
		end
		self._hasBeenWarmUp = true
		self._coWarmUp = nil
	end)
end

function MournPlotDialog:OnInitialize()
	---@type Engine.Lib.CoWait
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		local parameters = self.controller.Argument.parameters
		self.chapterId = parameters.chapterId
		self:RefreshChapterNode()
	end))
	return coWait
end

function MournPlotDialog:OnFinalize()
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
		self:Delete()
		self = nil --lua层的gc需要
	end))
	return coWait
end
--endregion lifecycle
function MournPlotDialog:RefreshChapterNode()
	local data = ActivityMournUtils.GetPlotVos(self.chapterId)
	if  isNull(data) then
		return
	end
	
	self.BtnCheckpointList.Scroller.Draggable = table.count(data) > 5
	
	self._data = data
	for i, v in pairs(self._data) do
		v.index = i
		v.callBack = Bind(self,self.OnBtnNodeClick)
	end
	
	if self._coFillSelf then
		cs_coroutine.stop(self._coFillSelf)
		self._coFillSelf = nil
	end
	self._coFillSelf = cs_coroutine.start(function()
	--[[	if not self._hasBeenWarmUp then
			self:WarmUp()
		end
		while not isNull(self._coWarmUp) do
			cs_coroutine.yield_return(nil)
		end]]
		CfUtils.SetActive(self.BtnCheckpointList, false)
		self.BtnCheckpointList:InitListView(0, self._data)
		CfUtils.SetActive(self.BtnCheckpointList, true)
		self.BtnCheckpointList:InitListView(table.count(self._data), self._data)
		self.BtnCheckpointList.OnIndexChanged = Bind(self, self.OnSelectCell)
		--self.BtnCheckpointList:MovePanelToIndex(3)
		
		self:RefreshShow()
		
		
		self._coFillSelf = nil
	end)
end

function MournPlotDialog:OnBtnNodeClick(index)
	if isNotNull(self.curIndex) and self.curIndex == index then
		return
	end
	
	local lastIndex = self.curIndex
	self:SetSelectState(lastIndex,false)
	self.curIndex = index
	self:SetSelectState(self.curIndex,true)
	self:RefreshChapterInfo()
end

function MournPlotDialog:SetLockState(index,state)
	if isNull(index) then
		return
	end
	local cell = self.BtnCheckpointList:GetShownItemByItemIndex(index - 1)
	if isNotNull(cell) then
		local env = CfUtils.GetLuaScr(cell.gameObject,"Game.Activity.Mourn.MournPlotCell")
		if isNotNull(env) then
			env:SetLockState(state)
		end
	end
	
	local cell = self.BtnCheckpointList:GetShownItemByItemIndex(self.curIndex - 1)
	if isNotNull(cell) then
		local env = CfUtils.GetLuaScr(cell.gameObject,"Game.Activity.Mourn.MournPlotCell")
		if isNotNull(env) then
			env:SetFinishState(true)
		end
	end
end

function MournPlotDialog:RefreshChapterInfo()
	local vo = self._data[self.curIndex]
	if isNotNull(vo) then
		local num = vo.index > 10 and vo.index or "0"..vo.index
		CfUtils.FillText(self.TxtNumber,num)
		CfUtils.FillText(self.ChapterDesc,vo.desc)
		local chapterVo = CfUtils.GetCfVo(AutoIds.IdSetting6613, "MournPlotChapterVo", vo.chapter)
		if isNotNull(chapterVo) then
			CfUtils.FillImage(self.ImgChapterPic,chapterVo.picture2)
		end
		local isFinish = ActivityMournUtils.IsUnLockPlot(vo.id)
		if isFinish then
			CfUtils.SetActive(self.Lock.gameObject,false)
			CfUtils.SetActive(self.Open.gameObject,true)
			CfUtils.SetActive(self.CommonBtnConsumePop.gameObject,false)
			CfUtils.FillText(self.Text,localize("回看"))
		else
			local isUnLock = ActivityMournUtils.IsUnLockPlot(vo.unlockPlot)
			CfUtils.SetActive(self.Lock.gameObject,not isUnLock)
			CfUtils.SetActive(self.Open.gameObject, isUnLock)
			CfUtils.FillText(self.Text,localize("前往"))
			if isUnLock  then
				local isUse = ActivityMournUtils.IsUseItem(vo)
				CfUtils.SetActive(self.CommonBtnConsumePop.gameObject, not isUse)
				if not isUse then
					UICommonUtils.FillCommonBtnConsumePop(self.CommonBtnConsumePop, vo.unlockItem, vo.unlockNum)
				end
			end
		end
	end
end

function MournPlotDialog:SetSelectState(index, state)
	if isNull(index) then
		return
	end
	local cell = self.BtnCheckpointList:GetShownItemByItemIndex(index - 1)
	if isNotNull(cell) then
		local env = CfUtils.GetLuaScr(cell.gameObject,"Game.Activity.Mourn.MournPlotCell")
		if isNotNull(env) then
			env:SetSelectState(state)
		end
	end
end

